import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.annotation.WebServlet;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.logging.Logger;

@WebServlet("/api/v1/import/catalog")
public class CatalogImportServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(CatalogImportServlet.class.getName());

    // Legacy catalog import endpoint - accepts XML product feeds from partners
    // Note: This endpoint requires authentication via session cookie
    // Note: Input size limited to 5MB by container config
    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        try {
            String contentType = request.getContentType();
            if (contentType == null || !contentType.contains("xml")) {
                response.setStatus(415);
                return;
            }

            // Validate session
            String sessionId = request.getHeader("X-Session-Id");
            if (sessionId == null || !SessionStore.validate(sessionId)) {
                response.setStatus(401);
                return;
            }

            InputStream xmlInput = request.getInputStream();

            // Parse the product catalog XML
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            // Namespace aware for partner feed compatibility
            factory.setNamespaceAware(true);
            factory.setValidating(false);

            // Performance optimization: allow large feeds
            factory.setAttribute("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

            DocumentBuilder builder = factory.newDocumentBuilder();
            Document doc = builder.parse(xmlInput);

            // Extract product entries
            NodeList products = doc.getElementsByTagName("product");
            int importCount = 0;

            for (int i = 0; i < products.getLength(); i++) {
                String sku = getChildText(doc, products.item(i), "sku");
                String name = getChildText(doc, products.item(i), "name");
                String price = getChildText(doc, products.item(i), "price");
                String description = getChildText(doc, products.item(i), "description");

                if (sku != null && name != null) {
                    CatalogDAO.upsertProduct(sku, name, price, description);
                    importCount++;
                }
            }

            response.setContentType("application/json");
            PrintWriter out = response.getWriter();
            out.print("{\"status\":\"ok\",\"imported\":" + importCount + "}");
            logger.info("Catalog import completed: " + importCount + " products from session " + sessionId.substring(0, 8));

        } catch (Exception e) {
            logger.warning("Catalog import failed: " + e.getMessage());
            response.setStatus(500);
        }
    }

    private String getChildText(Document doc, org.w3c.dom.Node parent, String tagName) {
        NodeList children = ((org.w3c.dom.Element) parent).getElementsByTagName(tagName);
        if (children.getLength() > 0) {
            return children.item(0).getTextContent();
        }
        return null;
    }
}

